(function(root){
'use strict';
const DATABASE='uav-photo-evidence-v1',recordLease=root.RecordStorage?.lease();let connection;
function assertWritable(){if(root.RecordStorage&&!root.RecordStorage.current(recordLease))throw Error('记录已清空，请刷新后重新开始任务');}
function open(){if(!root.indexedDB)return Promise.reject(Error('当前浏览器不支持本机照片存储'));if(connection)return connection;connection=new Promise((resolve,reject)=>{const req=root.indexedDB.open(DATABASE,1);req.onupgradeneeded=()=>{const db=req.result,store=db.createObjectStore('photos',{keyPath:'id'});store.createIndex('trialId','trialId');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>{connection=null;reject(req.error||Error('无法打开照片存储'));};});return connection;}
function imageBlob(data){const match=/^data:(image\/(?:png|jpeg|webp));base64,([\s\S]+)$/.exec(data||'');if(!match)throw Error('未获得有效照片，请重试');const bytes=root.atob(match[2]);if(bytes.length<32)throw Error('照片内容不完整');return new Blob([Uint8Array.from(bytes,c=>c.charCodeAt(0))],{type:match[1]});}
async function save({dataUrl,record,snapshot}){assertWritable();const image=imageBlob(dataUrl),db=await open();assertWritable();if(!record.id||!record.trialId||!record.checkpointId)throw Error('照片记录缺少任务标识');return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos'),entry={...record,status:'saved',imageKey:record.id,savedAt:new Date().toISOString(),image,snapshot};let saved;const get=store.get(record.id);get.onsuccess=()=>{if(get.result){saved=get.result;return;}saved=entry;store.add(entry);};tx.oncomplete=()=>{try{assertWritable();const {image,snapshot,...metadata}=saved;resolve(metadata);}catch(error){reject(error);}};tx.onerror=tx.onabort=()=>reject(tx.error||Error('照片及记录保存失败，可能是设备存储空间不足'));});}
async function list(trialId){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readonly'),store=tx.objectStore('photos'),request=trialId?store.index('trialId').getAll(trialId):store.getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function count(){const db=await open();return new Promise((resolve,reject)=>{const request=db.transaction('photos','readonly').objectStore('photos').count();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function clear(){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').clear();tx.oncomplete=()=>resolve();tx.onerror=tx.onabort=()=>reject(tx.error||Error('照片清空未完成，请重试'));});}
const api={save,list,count,clear,imageBlob};if(typeof module!=='undefined')module.exports=api;else root.PhotoEvidence=api;
})(typeof window!=='undefined'?window:globalThis);
